\section{Introduction}

\subsection{The problem}
Let $A$ be an abelian group, regarded throughout as a module over $\Z$. An
\emph{extension of $A$ by $\Z$} is a short exact sequence of abelian groups
\[
0 \longrightarrow \Z \xrightarrow{\;i\;} G \xrightarrow{\;p\;} A \longrightarrow 0,
\]
meaning $i$ is injective, $p$ is surjective, and $\range(i)=\ker(p)$. The extension
\emph{splits} if $p$ admits a $\Z$-linear section $s:A\to G$ with $p\circ
s=\id_A$; equivalently $G\cong\Z\oplus A$. Isomorphism classes of extensions form
the group $\Ext^1(A,\Z)$, whose zero element is the split extension. Whitehead asked:
if $\Ext^1(A,\Z)=0$, must $A$ be free? Groups satisfying the hypothesis are called
\emph{Whitehead groups}.

\subsection{The independence phenomenon}
The finitely generated case is classical: a finitely generated Whitehead group is
free. Stein extended this to countable groups. Shelah (1974) proved that ``every
Whitehead group is free'' is \emph{independent of ZFC}: a theorem under $V=L$ and
refutable under $\mathrm{MA}+\neg\mathrm{CH}$. Independence is a statement about the
class of models of ZFC and cannot be captured by a single object-level proposition.
What can be captured, and is the subject of this paper, is the layer of theory that
every model of ZFC agrees on.

\subsection{Contributions}
We make the splitting formulation precise and prove three mutually reinforcing
results, all valid in ZFC: projective $\Rightarrow$ Whitehead (Theorem~\ref{thm:proj});
projective $\Rightarrow$ torsion-free (Theorem~\ref{thm:tf}); and the cyclic torsion
obstruction (Theorem~\ref{thm:obs}).

\section{Definitions}
Throughout, ``group'' means abelian group, identified with a $\Z$-module, and
``linear'' means $\Z$-linear.

\begin{definition}[Whitehead group]
An abelian group $A$ is a \emph{Whitehead group} if for every abelian group $G$,
every linear injection $i:\Z\to G$, and every linear surjection $p:G\to A$ with
$\range(i)=\ker(p)$, there exists a linear map $s:A\to G$ with $p\circ s=\id_A$.
\end{definition}

\begin{definition}[Projective module]
A $\Z$-module $A$ is \emph{projective} if for every surjective linear map
$f:M\twoheadrightarrow A$ there is a linear section $\sigma:A\to M$ with
$f\circ\sigma=\id_A$; equivalently, $A$ is a direct summand of a free module.
\end{definition}

\begin{definition}[Torsion-free]
A $\Z$-module $A$ is \emph{torsion-free} if for every $r\ne 0$ and $a\in A$,
$r\cdot a=0$ implies $a=0$.
\end{definition}

\begin{definition}[Cyclic group $\Z/n$]
For $n\ge 1$, $\Z/n$ denotes the integers modulo $n$, a finite abelian group of
order $n$ with $n\cdot x=0$ for all $x$; for $n\ge 2$ it contains nonzero torsion.
\end{definition}

\section{Main results}

\subsection{Projective groups are Whitehead groups}
\begin{theorem}[\texttt{isWhiteheadGroup\_of\_projective}]\label{thm:proj}
Let $A$ be an abelian group that is projective as a $\Z$-module. Then $A$ is a
Whitehead group.
\end{theorem}
\begin{proof}[Proof sketch]
Let $0\to\Z\xrightarrow{i}G\xrightarrow{p}A\to 0$ be any extension, so $p:G\to A$ is
surjective. Projectivity provides a section of any surjection onto $A$; applying
this to $p$ yields a linear $s:A\to G$ with $p\circ s=\id_A$, the required
splitting. (Formally the section is produced by the universal lifting property
\texttt{Module.projective\_lifting\_property} applied to $p$ and $\id_A$.) Neither
the injectivity of $i$ nor the exactness hypothesis is consumed: a surjection onto a
projective module always splits.
\end{proof}

\begin{remark}
Theorem~\ref{thm:proj} is strictly stronger than ``free $\Rightarrow$ Whitehead'':
free modules are projective, and phrasing the hypothesis as projectivity reduces the
proof to the defining lifting property, severing any circular dependence on the
structure theory of free modules.
\end{remark}

\subsection{Projective groups are torsion-free}
\begin{theorem}[\texttt{Module.IsTorsionFree.of\_projective\_int}]\label{thm:tf}
Every projective $\Z$-module $A$ is torsion-free.
\end{theorem}
\begin{proof}[Proof sketch]
Projectivity gives a linear section $s:A\to(A\to_0\Z)$ of the canonical surjection
from the free module $A\to_0\Z$ of finitely supported integer-valued functions on
$A$. Being a section, $s$ is injective. The free module $A\to_0\Z$ is a direct sum of
copies of $\Z$, hence torsion-free. If $r\cdot a=0$ with $r\ne 0$, then $r\cdot
s(a)=s(r\cdot a)=0$, so $s(a)=0$ by torsion-freeness of the codomain, and
injectivity gives $a=0$. (Formally,
\texttt{Function.Injective.moduleIsTorsionFree} applied to the section from
\texttt{Module.projective\_def}.)
\end{proof}

\begin{remark}
Theorem~\ref{thm:tf} explains \emph{why} the only obstruction to the Whitehead
property is torsion. It avoids the structure theorem, deriving torsion-freeness
directly from the splitting of the projective presentation.
\end{remark}

\subsection{The cyclic torsion obstruction}
\begin{theorem}[\texttt{not\_isWhiteheadGroup\_zmod}]\label{thm:obs}
For every integer $n\ge 2$, the cyclic group $\Z/n$ is \emph{not} a Whitehead group.
\end{theorem}
\begin{proof}[Proof sketch]
Consider the extension
\[
0 \longrightarrow \Z \xrightarrow{\;\cdot n\;} \Z \xrightarrow{\;\bmod n\;} \Z/n
\longrightarrow 0,
\]
with first map multiplication by $n$ and second map reduction modulo $n$. It is a
genuine extension: $\cdot n$ is injective by cancellation in the domain $\Z$
($n\ne0$); $\bmod n$ is surjective; and an integer reduces to $0$ iff $n$ divides
it, so $\range(\cdot n)=\ker(\bmod n)$. Suppose toward contradiction that the
extension splits via a linear $s:\Z/n\to\Z$. For any $x\in\Z/n$, $n\cdot x=0$, so by
linearity $n\cdot s(x)=s(n\cdot x)=0$ in $\Z$; since $\Z$ is torsion-free and
$n\ne0$, $s(x)=0$. Hence $s=0$. But then $(\bmod n)\circ s=0\ne\id_{\Z/n}$ (the
identity sends $1\mapsto1\ne0$ as $n\ge2$), contradicting $p\circ s=\id$. So no
splitting exists.
\end{proof}

\begin{remark}
Theorem~\ref{thm:obs} shows torsion-freeness is a genuine \emph{necessary}
condition for the Whitehead property: any group with a direct summand $\Z/n$
inherits this obstruction.
\end{remark}

\section{The decidable boundary and the location of independence}

\begin{corollary}[Finitely generated case]
A finitely generated abelian group $A$ is a Whitehead group if and only if it is
free.
\end{corollary}
\begin{proof}[Argument]
By the structure theorem over the PID $\Z$, $A\cong\Z^r\oplus T$ with $T$ finite
torsion. If $T\ne0$ it contains a summand $\Z/n$ ($n\ge2$), whose obstruction
(Theorem~\ref{thm:obs}) lifts to $A$, so $A$ is not Whitehead; thus a finitely
generated Whitehead group is free $\Z^r$. Conversely $\Z^r$ is free, hence
projective, hence Whitehead by Theorem~\ref{thm:proj}. (The lifting across a direct
summand and the structure-theorem step are stated as Conjectures~\ref{conj:tf} and
\ref{conj:fg}; the endpoints, Theorems~\ref{thm:proj} and \ref{thm:obs}, are
established here.)
\end{proof}

In the finitely generated world there is no independence: Whitehead $=$ free,
provably in ZFC; the same holds for countable groups by Stein's theorem. Shelah's
independence lives strictly in the uncountable, non-finitely-generated realm, where
amalgamating uncountably many local sections is governed by combinatorial principles
($\diamondsuit$ under $V=L$ versus uniformization failures under
$\mathrm{MA}+\neg\mathrm{CH}$) that ZFC does not settle.

\section{Algorithms}
\subsection{Section extraction for split extensions}
Given $0\to\Z\to G\xrightarrow{p}A\to 0$ with $A$ projective and a presentation of
$A$ as a retract of a free module, construct $s$ by lifting each generator of $A$
along $p$ and extending linearly --- the algorithmic shadow of
Theorem~\ref{thm:proj}.

\subsection{Obstruction detection for cyclic summands}
Given a finitely generated abelian group in Smith normal form
$\bigoplus_i\Z/d_i$ (with $d_i=0$ for free factors), the group is Whitehead iff
every $d_i\in\{0,1\}$. Each $d_i\ge2$ certifies a non-split extension by
Theorem~\ref{thm:obs}; this is a decidable test.

\section{Applications and discussion}
Theorems~\ref{thm:proj}--\ref{thm:obs} instantiate, explicitly and basis-free, the
facts that $\Ext^1(P,-)=0$ for projective $P$ and
$\Ext^1(\Z/n,\Z)\cong\Z/n\ne0$. The decidable boundary yields a clean Whitehead
criterion on finitely generated and countable groups via torsion detection, and the
development is a case study in separating the ZFC-provable core of a theory from its
independent periphery. By design we do not formalize the independence metatheorem,
which quantifies over models of ZFC.

\section{Future directions}
The following are conjectures and program statements, not results proven here.

\begin{conjecture}[Whitehead $\Rightarrow$ torsion-free, full generality]\label{conj:tf}
If $A$ is Whitehead then $A$ is torsion-free. The cyclic counterexample realizes the
only obstruction; the general case follows by pushing it out along an injection
$\Z/n\hookrightarrow A$, i.e.\ surjectivity of $\Ext^1(A,\Z)\to\Ext^1(\Z/n,\Z)\cong
\Z/n$ from $\Z$ having global dimension $1$.
\end{conjecture}

\begin{conjecture}[Finitely generated Whitehead $\Leftrightarrow$ free]\label{conj:fg}
For finitely generated $A$, $A$ is Whitehead iff $A$ is free: the structure theorem
gives $A\cong\Z^r\oplus(\text{torsion})$, Conjecture~\ref{conj:tf} kills the torsion,
and $\Z^r$ is Whitehead by Theorem~\ref{thm:proj}.
\end{conjecture}

\begin{conjecture}[Stein's theorem]
Every countable Whitehead group is free, proved by filtering $A$ by a chain of
finitely generated pure subgroups with finitely generated torsion-free (hence free)
quotients, killing the extension class at each step.
\end{conjecture}

\begin{conjecture}[Finite biproduct additivity]
$\prod_{i\in\mathrm{Fin}\,k}A_i$ is Whitehead iff each $A_i$ is, the $k$-fold
generalization of binary additivity via a $\mathrm{Fin}\,k$ induction, with the
section over a finite product given by the sum of componentwise sections.
\end{conjecture}

\section{Conclusion}
We have delineated the ZFC-provable skeleton of the Whitehead problem: projectivity
guarantees the Whitehead property (Theorem~\ref{thm:proj}); projective groups are
torsion-free (Theorem~\ref{thm:tf}); and torsion provably obstructs the property,
with $\Z/n$ ($n\ge2$) an explicit witness (Theorem~\ref{thm:obs}). These fix the
decidable boundary --- free $=$ Whitehead for finitely generated groups --- and
locate Shelah's independence precisely in the uncountable beyond.

